            </Link>
          </h3>
          <p className="record-list__summary">
            {fixture.season} / {labelValue(fixture.gender)} /{' '}
            {fixture.scheduledOvers === null
              ? 'Overs not specified'
              : `${fixture.scheduledOvers} overs`}
          </p>
        </RecordListItem>
      )}
      resourceLabel="fixtures"
      title="Fixtures"
